import { motion } from 'motion/react';
import { Link } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { Star, Quote } from 'lucide-react';
import { Helmet } from '@dr.pogodin/react-helmet';
import { useState } from 'react';

const fadeUp = {
  hidden: { opacity: 0, y: 24 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.35, ease: 'easeOut' as const } },
};

const stagger = {
  hidden: {},
  visible: { transition: { staggerChildren: 0.1 } },
};

// ─── Data ─────────────────────────────────────────────────────────────────────
const reviews = [
  {
    name: 'Sarah M.',
    location: 'Regular client · 2 years',
    rating: 5,
    service: 'Regular Cleaning',
    review:
      "I've tried a few cleaning services over the years, but SpotlessHome is the only one I keep coming back to. My kitchen has never looked this good. She remembers exactly how I like things and always goes the extra mile.",
  },
  {
    name: 'James T.',
    location: 'Deep Clean client',
    rating: 5,
    service: 'Deep Cleaning',
    review:
      "Booked a deep clean before my in-laws visited. They actually asked if I remodeled. Worth every penny. The bathroom grout alone looked brand new — I didn't even know it could look like that.",
  },
  {
    name: 'Priya K.',
    location: 'Move-Out client',
    rating: 5,
    service: 'Move-In / Move-Out',
    review:
      "The move-out clean was incredible. Got my full security deposit back — my landlord was shocked at how clean it was. She cleaned things I didn't even think to ask about. Absolutely recommend.",
  },
  {
    name: 'Marcus & Linda R.',
    location: 'Regular clients · 3 years',
    rating: 5,
    service: 'Regular Cleaning',
    review:
      "We have two dogs and a toddler. Our house gets destroyed every week. SpotlessHome comes in and makes it feel like a brand new home every time. We honestly don't know what we'd do without her.",
  },
  {
    name: 'Diane F.',
    location: 'Deep Clean client',
    rating: 5,
    service: 'Deep Cleaning',
    review:
      "I was nervous about letting someone into my home, but from the first visit I felt completely at ease. She's professional, thorough, and genuinely cares about doing a great job. My oven looks brand new.",
  },
  {
    name: 'Tom H.',
    location: 'Move-In client',
    rating: 5,
    service: 'Move-In / Move-Out',
    review:
      "Hired SpotlessHome to clean our new place before we moved in. The previous tenants had left it in rough shape. She transformed it completely — we moved in feeling like it was a fresh start. Highly recommend.",
  },
];

const beforeAfter = [
  {
    label: 'Kitchen Deep Clean',
    before: '/airo-assets/images/pages/reviews/before-kitchen',
    after: '/airo-assets/images/pages/reviews/after-kitchen',
    beforeAlt: 'Kitchen before cleaning',
    afterAlt: 'Kitchen after deep cleaning — spotless and bright',
  },
  {
    label: 'Bathroom Refresh',
    before: '/airo-assets/images/services/deep-cleaning',
    after: '/airo-assets/images/pages/reviews/after-bathroom',
    beforeAlt: 'Bathroom before cleaning',
    afterAlt: 'Bathroom after deep cleaning — sparkling white',
  },
];

// ─── Before/After slider component ───────────────────────────────────────────
function BeforeAfterCard({ item }: { item: typeof beforeAfter[0] }) {
  const [showAfter, setShowAfter] = useState(false);

  return (
    <motion.div
      variants={fadeUp}
      className="flex flex-col gap-3"
    >
      <div className="relative overflow-hidden rounded-2xl shadow-lg aspect-video cursor-pointer group"
        onClick={() => setShowAfter((v) => !v)}
      >
        {/* Before */}
        <img
          src={item.before}
          alt={item.beforeAlt}
          className={`absolute inset-0 w-full h-full object-cover transition-opacity duration-500 ${showAfter ? 'opacity-0' : 'opacity-100'}`}
        />
        {/* After */}
        <img
          src={item.after}
          alt={item.afterAlt}
          className={`absolute inset-0 w-full h-full object-cover transition-opacity duration-500 ${showAfter ? 'opacity-100' : 'opacity-0'}`}
        />
        {/* Label */}
        <div className="absolute bottom-3 left-3 right-3 flex justify-between pointer-events-none">
          <span className={`text-xs font-semibold px-3 py-1 rounded-full transition-colors duration-300 ${!showAfter ? 'bg-gray-900/80 text-white' : 'bg-gray-900/30 text-white/60'}`}>
            Before
          </span>
          <span className={`text-xs font-semibold px-3 py-1 rounded-full transition-colors duration-300 ${showAfter ? 'bg-primary text-primary-foreground' : 'bg-gray-900/30 text-white/60'}`}>
            After
          </span>
        </div>
        {/* Tap hint */}
        <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-200">
          <span className="bg-black/40 text-white text-xs font-medium px-3 py-1.5 rounded-full backdrop-blur-sm">
            Tap to toggle
          </span>
        </div>
      </div>
      <p className="text-sm font-semibold text-foreground text-center">{item.label}</p>
    </motion.div>
  );
}

// ─── Stars ────────────────────────────────────────────────────────────────────
function Stars({ count }: { count: number }) {
  return (
    <div className="flex gap-0.5">
      {Array.from({ length: count }).map((_, i) => (
        <Star key={i} size={13} className="fill-primary text-primary" />
      ))}
    </div>
  );
}

// ─── Page ─────────────────────────────────────────────────────────────────────
export default function ReviewsPage() {
  return (
    <>
      <Helmet>
        <title>Reviews & Results - SpotlessHome</title>
        <meta
          name="description"
          content="See what real customers say about SpotlessHome. 5-star reviews and before & after photos from satisfied families."
        />
      </Helmet>

      <main>
        {/* ── Hero ── */}
        <section className="py-20 bg-primary/10">
          <div className="container mx-auto px-4">
            <motion.div
              className="max-w-xl"
              initial="hidden"
              animate="visible"
              variants={stagger}
            >
              <motion.p variants={fadeUp} className="text-primary font-semibold text-sm uppercase tracking-widest mb-3">
                Real Customers, Real Results
              </motion.p>
              <motion.h1 variants={fadeUp} className="text-5xl md:text-6xl font-bold text-foreground mb-4 leading-tight">
                Reviews &<br />Results
              </motion.h1>
              <motion.p variants={fadeUp} className="text-foreground/70 text-lg leading-relaxed">
                Don't just take my word for it. Here's what families across the area are saying — and what their homes look like after a visit.
              </motion.p>

              {/* Summary stats */}
              <motion.div variants={fadeUp} className="flex gap-8 mt-8">
                <div>
                  <p className="text-4xl font-bold text-foreground">5.0</p>
                  <Stars count={5} />
                  <p className="text-xs text-foreground/50 mt-1">Average rating</p>
                </div>
                <div className="w-px bg-border" />
                <div>
                  <p className="text-4xl font-bold text-foreground">100+</p>
                  <p className="text-xs text-foreground/50 mt-1">Happy clients</p>
                </div>
                <div className="w-px bg-border" />
                <div>
                  <p className="text-4xl font-bold text-foreground">8+</p>
                  <p className="text-xs text-foreground/50 mt-1">Years in business</p>
                </div>
              </motion.div>
            </motion.div>
          </div>
        </section>

        {/* ── Reviews grid ── */}
        <section className="py-24 bg-background">
          <div className="container mx-auto px-4">
            <motion.div
              className="text-center mb-14"
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
              variants={stagger}
            >
              <motion.p variants={fadeUp} className="text-primary font-semibold text-sm uppercase tracking-widest mb-3">
                What Clients Say
              </motion.p>
              <motion.h2 variants={fadeUp} className="text-4xl md:text-5xl font-bold text-foreground">
                Customer Reviews
              </motion.h2>
            </motion.div>

            <motion.div
              className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6"
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
              variants={stagger}
            >
              {reviews.map((r) => (
                <motion.div
                  key={r.name}
                  variants={fadeUp}
                  whileHover={{ y: -4, transition: { duration: 0.2 } }}
                  className="bg-background rounded-2xl p-6 border border-border/30 shadow-sm flex flex-col gap-4"
                >
                  <div className="flex items-start justify-between gap-2">
                    <Stars count={r.rating} />
                    <Quote size={18} className="text-primary/30 shrink-0" />
                  </div>
                  <p className="text-foreground/75 text-sm leading-relaxed flex-1">"{r.review}"</p>
                  <div className="pt-2 border-t border-border/30">
                    <p className="font-semibold text-foreground text-sm">{r.name}</p>
                    <p className="text-xs text-foreground/50">{r.location}</p>
                    <span className="inline-block mt-1.5 text-xs bg-primary/10 text-primary font-medium px-2 py-0.5 rounded-full">
                      {r.service}
                    </span>
                  </div>
                </motion.div>
              ))}
            </motion.div>
          </div>
        </section>

        {/* ── Before & After ── */}
        <section className="py-24" style={{ background: 'hsl(60 30% 97%)' }}>
          <div className="container mx-auto px-4">
            <motion.div
              className="text-center mb-14"
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
              variants={stagger}
            >
              <motion.p variants={fadeUp} className="text-primary font-semibold text-sm uppercase tracking-widest mb-3">
                See the Difference
              </motion.p>
              <motion.h2 variants={fadeUp} className="text-4xl md:text-5xl font-bold text-foreground">
                Before & After
              </motion.h2>
              <motion.p variants={fadeUp} className="text-foreground/60 mt-3">
                Tap any photo to toggle between before and after.
              </motion.p>
            </motion.div>

            <motion.div
              className="grid grid-cols-1 md:grid-cols-2 gap-8 max-w-3xl mx-auto"
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
              variants={stagger}
            >
              {beforeAfter.map((item) => (
                <BeforeAfterCard key={item.label} item={item} />
              ))}
            </motion.div>
          </div>
        </section>

        {/* ── CTA ── */}
        <section className="py-20 bg-primary/10">
          <div className="container mx-auto px-4">
            <motion.div
              className="flex flex-col md:flex-row items-center justify-between gap-8"
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
              variants={stagger}
            >
              <motion.div variants={fadeUp} className="max-w-lg">
                <h2 className="text-3xl md:text-4xl font-bold text-foreground mb-3">
                  Ready to see results like these in your home?
                </h2>
                <p className="text-foreground/70">
                  Join hundreds of happy families. Get a free quote today — I'd love to add your home to the list.
                </p>
              </motion.div>
              <motion.div variants={fadeUp} className="shrink-0">
                <Button asChild size="lg" className="rounded-full px-10">
                  <Link to="/contact">Get a Free Quote</Link>
                </Button>
              </motion.div>
            </motion.div>
          </div>
        </section>
      </main>
    </>
  );
}

